// Validate, normalise and de-duplicate the target URLs
const seen = new Set();
const out = [];
$input.all().forEach((item, i) => {
  let raw = String(item.json.url ?? item.json.URL ?? item.json.Url ?? '').trim();
  if (!raw) return;
  if (!/^https?:\/\//i.test(raw)) raw = 'https://' + raw;
  let parsed;
  try { parsed = new URL(raw); } catch (e) { return; }
  const key = parsed.href.replace(/\/$/, '').toLowerCase();
  if (seen.has(key)) return;
  seen.add(key);
  out.push({ json: { url: parsed.href }, pairedItem: { item: i } });
});
return out;

// Turns the Jina Reader response into a Gemini structured-output request
const cfg = $('Workflow Config').first().json;
const MODEL = cfg.gemini_model || 'gemini-2.5-flash';
const MAX_CHARS = Number(cfg.max_page_chars) || 60000;

const errText = (e) => {
  if (!e) return 'unknown error';
  if (typeof e === 'string') return e.slice(0, 300);
  return String(e.message || e.description || JSON.stringify(e)).slice(0, 300);
};

const S = { type: 'STRING', nullable: true };
const schema = {
  type: 'OBJECT',
  properties: {
    company: {
      type: 'OBJECT',
      properties: {
        name: S, website: S, industry: S, description: S, headquarters: S,
        employee_count_range: S, general_email: S, general_phone: S,
        linkedin_url: S, twitter_url: S, facebook_url: S, instagram_url: S, youtube_url: S
      },
      required: ['name']
    },
    contacts: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          first_name: S, last_name: S, full_name: { type: 'STRING' },
          job_title: S, department: S, email: S, phone: S,
          linkedin_url: S, twitter_url: S, location: S,
          confidence: { type: 'NUMBER' }
        },
        required: ['full_name', 'confidence']
      }
    }
  },
  required: ['company', 'contacts']
};

const SYSTEM = [
  'You are a B2B lead-extraction engine.',
  'You receive a web page converted to markdown, plus its social/contact links.',
  'Extract the company profile and every named person who works at (or represents) the company.',
  'Rules:',
  '1. Use ONLY information explicitly present in the input. Never guess or invent emails, phone numbers or URLs.',
  '2. Emails must appear literally in the input. Use null for any field that is not present.',
  '3. Return absolute https URLs. Do not return relative links.',
  '4. Exclude customers, testimonial authors, blog-post authors and people who are clearly not staff of the company.',
  '5. Do not return the same person twice.',
  '6. confidence is 0 to 1: how completely and unambiguously the page supports that contact record.'
].join('\n');

const SOCIAL_RE = /(linkedin\.com|twitter\.com|x\.com|facebook\.com|instagram\.com|youtube\.com|tiktok\.com|github\.com|mailto:|tel:)/i;
const EMAIL_RE = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g;
const BAD_EMAIL = /\.(png|jpe?g|gif|svg|webp|css|js)$/i;

const out = [];
$input.all().forEach((item, i) => {
  const source_url = $('Normalize URLs').itemMatching(i).json.url;
  const logged_at = new Date().toISOString();
  const data = item.json && item.json.data;

  if (!data || !data.content || item.json.error) {
    out.push({
      json: {
        _status: 'failed', source_url,
        error: 'Jina Reader failed: ' + errText(item.json && (item.json.error || item.json.message) || 'empty content'),
        logged_at
      },
      pairedItem: { item: i }
    });
    return;
  }

  let md = String(data.content)
    .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  if (md.length > MAX_CHARS) md = md.slice(0, MAX_CHARS) + '\n\n[TRUNCATED]';

  // Jina returns links as an object {text: url} or as an array of [text, url]
  const raw = data.links;
  let pairs = [];
  if (Array.isArray(raw)) pairs = raw.map(l => Array.isArray(l) ? l : [l && l.text, l && (l.url || l.href)]);
  else if (raw && typeof raw === 'object') pairs = Object.entries(raw);
  const links = pairs
    .map(([t, u]) => ({ text: String(t || '').slice(0, 80), url: String(u || '') }))
    .filter(l => SOCIAL_RE.test(l.url))
    .slice(0, 80);

  const found = new Set();
  const scan = (txt) => (String(txt).match(EMAIL_RE) || []).forEach(e => {
    e = e.toLowerCase();
    if (!BAD_EMAIL.test(e)) found.add(e);
  });
  scan(md);
  links.forEach(l => scan(l.url));
  const emails_found = [...found].slice(0, 300);

  const userText = [
    'SOURCE_URL: ' + source_url,
    'PAGE_TITLE: ' + (data.title || ''),
    'PAGE_DESCRIPTION: ' + (data.description || ''),
    'EMAILS_FOUND_BY_REGEX: ' + (emails_found.join(', ') || 'none'),
    'SOCIAL_AND_CONTACT_LINKS:',
    links.map(l => '- ' + l.text + ' | ' + l.url).join('\n') || 'none',
    '',
    'PAGE_MARKDOWN:',
    md
  ].join('\n');

  const generationConfig = {
    responseMimeType: 'application/json',
    responseSchema: schema,
    maxOutputTokens: 16384
  };
  // Sampling / thinking knobs only for the 2.x family (newer models deprecate them)
  if (/^gemini-2\./.test(MODEL)) {
    generationConfig.temperature = 0;
    generationConfig.maxOutputTokens = 8192;
    if (/flash/.test(MODEL)) generationConfig.thinkingConfig = { thinkingBudget: 0 };
  }

  out.push({
    json: {
      _status: 'ok',
      source_url,
      model: MODEL,
      page_title: data.title || '',
      emails_found,
      geminiRequest: {
        systemInstruction: { parts: [{ text: SYSTEM }] },
        contents: [{ role: 'user', parts: [{ text: userText }] }],
        generationConfig
      }
    },
    pairedItem: { item: i }
  });
});
return out;

// Parses Gemini's JSON, validates it, and explodes it into one item per contact
const out = [];
const now = new Date().toISOString();

const errText = (e) => {
  if (!e) return 'unknown error';
  if (typeof e === 'string') return e.slice(0, 300);
  return String(e.message || e.description || JSON.stringify(e)).slice(0, 300);
};
const clean = (v) => {
  if (v === null || v === undefined) return '';
  const s = String(v).trim();
  return /^(null|n\/a|none|unknown|undefined|-)$/i.test(s) ? '' : s;
};
const cleanEmail = (v) => {
  const e = clean(v).toLowerCase().replace(/^mailto:/, '');
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e) ? e : '';
};
const cleanUrl = (v) => {
  let u = clean(v);
  if (!u) return '';
  if (!/^https?:\/\//i.test(u)) u = 'https://' + u.replace(/^\/+/, '');
  try { return new URL(u).href; } catch (e) { return ''; }
};
const cleanPhone = (v) => clean(v).replace(/[^\d+()\-.\s]/g, '').trim();
const clamp = (n, d) => {
  n = Number(n);
  return Number.isFinite(n) ? Math.min(1, Math.max(0, n)) : d;
};

$input.all().forEach((item, i) => {
  const ctx = $('Prepare Gemini Payload').itemMatching(i).json;
  const source_url = ctx.source_url;
  const emailsFound = ctx.emails_found || [];
  const fail = (msg) => out.push({
    json: { _status: 'failed', source_url, error: msg, logged_at: now },
    pairedItem: { item: i }
  });

  if (item.json.error) return fail('Gemini request failed: ' + errText(item.json.error));

  let parsed;
  try {
    const cand = item.json.candidates && item.json.candidates[0];
    const text = ((cand && cand.content && cand.content.parts) || []).map(p => p.text || '').join('');
    if (!text) {
      throw new Error('empty response (' + ((cand && cand.finishReason) ||
        (item.json.promptFeedback && item.json.promptFeedback.blockReason) || 'unknown') + ')');
    }
    parsed = JSON.parse(text);
  } catch (e) {
    return fail('Gemini JSON parse error: ' + e.message);
  }

  const co = parsed.company || {};
  const company = {
    company_name: clean(co.name) || clean(ctx.page_title),
    company_website: cleanUrl(co.website) || source_url,
    company_industry: clean(co.industry),
    company_description: clean(co.description),
    company_hq: clean(co.headquarters),
    company_size: clean(co.employee_count_range),
    company_linkedin_url: cleanUrl(co.linkedin_url),
    company_twitter_url: cleanUrl(co.twitter_url),
    company_facebook_url: cleanUrl(co.facebook_url),
    company_instagram_url: cleanUrl(co.instagram_url),
    company_youtube_url: cleanUrl(co.youtube_url)
  };

  const build = (c, record_type, defaultConfidence) => {
    let first = clean(c.first_name);
    let last = clean(c.last_name);
    let full = clean(c.full_name) || [first, last].filter(Boolean).join(' ');
    if (full && !first) {
      const parts = full.split(/\s+/);
      first = parts[0];
      last = last || parts.slice(1).join(' ');
    }
    // Anti-hallucination: keep an email only if it literally exists in the crawled page
    let email = cleanEmail(c.email);
    if (email && !emailsFound.includes(email)) email = '';

    const rec = {
      record_type,
      full_name: full, first_name: first, last_name: last,
      job_title: clean(c.job_title), department: clean(c.department),
      email, phone: cleanPhone(c.phone),
      contact_linkedin_url: cleanUrl(c.linkedin_url),
      contact_twitter_url: cleanUrl(c.twitter_url),
      location: clean(c.location),
      ...company,
      confidence: clamp(c.confidence, defaultConfidence),
      source_url,
      scraped_at: now,
      _status: 'ok'
    };
    rec.dedupe_key = (rec.email || rec.contact_linkedin_url ||
      ((rec.full_name || rec.company_name) + '|' + rec.company_name)).toLowerCase();
    return rec;
  };

  const seen = new Set();
  const records = [];
  (Array.isArray(parsed.contacts) ? parsed.contacts : []).forEach(c => {
    const r = build(c, 'person', 0.5);
    if (!r.full_name && !r.email) return;
    if (seen.has(r.dedupe_key)) return;
    seen.add(r.dedupe_key);
    records.push(r);
  });

  // No people found: fall back to a company-level lead (general inbox / phone)
  if (!records.length) {
    const ge = cleanEmail(co.general_email);
    const gp = cleanPhone(co.general_phone);
    if ((ge && emailsFound.includes(ge)) || gp) {
      const r = build({ full_name: '', email: ge, phone: gp, confidence: 0.5 }, 'company_general', 0.5);
      r.confidence = 0.5;
      records.push(r);
    }
  }

  if (!records.length) return fail('No contact entities found on page');
  records.forEach(r => out.push({ json: r, pairedItem: { item: i } }));
});
return out;

// Builds HubSpot batch-upsert payloads (max 100 contacts / request), skipping blank values
const cfg = $('Workflow Config').first().json;
const MIN = Number(cfg.min_confidence !== undefined ? cfg.min_confidence : 0.5);

const best = new Map();
$input.all().forEach(({ json: r }) => {
  if (!r.email || Number(r.confidence) < MIN) return;
  const prev = best.get(r.email);
  if (!prev || Number(r.confidence) > Number(prev.confidence)) best.set(r.email, r);
});

const inputs = [...best.values()].map(r => {
  const raw = {
    // standard HubSpot contact properties
    firstname: r.first_name,
    lastname: r.last_name,
    jobtitle: r.job_title,
    phone: r.phone,
    company: r.company_name,
    website: r.company_website,
    // custom properties (create these in HubSpot first, internal names below)
    crawler_source_url: r.source_url,
    crawler_department: r.department,
    crawler_contact_linkedin: r.contact_linkedin_url,
    crawler_contact_twitter: r.contact_twitter_url,
    crawler_company_industry: r.company_industry,
    crawler_company_size: r.company_size,
    crawler_company_description: (r.company_description || '').slice(0, 1000),
    crawler_company_linkedin: r.company_linkedin_url,
    crawler_company_twitter: r.company_twitter_url,
    crawler_company_facebook: r.company_facebook_url,
    crawler_company_instagram: r.company_instagram_url,
    crawler_confidence: Number(r.confidence),
    crawler_scraped_at: r.scraped_at
  };
  const properties = {};
  for (const [k, v] of Object.entries(raw)) {
    if (v === '' || v === null || v === undefined) continue;
    properties[k] = v;
  }
  return { idProperty: 'email', id: r.email, properties };
});

const out = [];
for (let i = 0; i < inputs.length; i += 100) {
  out.push({ json: { inputs: inputs.slice(i, i + 100) } });
}
return out;
